<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Requests\{ApplyProviderRequest,ReviewProviderApplicationRequest}; use App\Models\ProviderApplication; use App\Services\ProviderApplicationService; use Illuminate\Http\Request;
class ProviderApplicationController extends ApiController { public function __construct(private ProviderApplicationService $service){} public function store(ApplyProviderRequest $r){return response()->json(['data'=>$this->service->apply($r->user(),$r->validated()),'meta'=>[]],201);} public function mine(Request $r){return $this->success(ProviderApplication::where('user_id',$r->user()->id)->latest()->first());} public function index(Request $r){$this->admin($r);return $this->success(ProviderApplication::with(['user','category'])->latest()->paginate(20));} public function show(Request $r,ProviderApplication $application){$this->admin($r);return $this->success($application->load(['user','category']));} public function approve(Request $r,ProviderApplication $application){$this->admin($r);return $this->success($this->service->approve($application,$r->user()));} public function reject(ReviewProviderApplicationRequest $req,ProviderApplication $application){$this->admin($req);return $this->success($this->service->reject($application,$req->user(),$req->validated()['reason']));} private function admin(Request $r):void{abort_unless($r->user()->roles()->whereIn('name',['ADMIN','SUPER_ADMIN'])->exists(),403);} }
